// Returns first index in [0,n] where condition(i) is true.
int binarySearch(int n) {
    int lo = 0, hi = n;            // half-open [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;   // overflow-safe
        if (condition(mid)) hi = mid;   // answer is mid or left
        else                lo = mid + 1; // answer is strictly right
    }
    return lo;   // == hi: the boundary
}

def binary_search(n, condition):
    lo, hi = 0, n            # half-open [lo, hi)
    while lo < hi:
        mid = (lo + hi) // 2
        if condition(mid):
            hi = mid          # answer is mid or to the left
        else:
            lo = mid + 1      # answer is strictly to the right
    return lo

def search_rotated(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[lo] <= a[mid]:              # left half sorted
            if a[lo] <= target < a[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:                            # right half sorted
            if a[mid] < target <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1
